// CRM workspace v2. Inlined into the standalone HTML by build-workspace.mjs.
const oldField=field,oldFormData=formData,oldEdit=editForm,oldAction=action,oldProjects=projectDetail,oldTasks=tasks,oldSettings=settings,oldServices=services;
let accountId=null,accountTab='overview',contactQuery='',companyQuery='',contactStatus='',supportStatus='',agendaOffset=0;
let filters={q:'',stage:'',owner:'',event:'',risk:'',mode:'list'};
let companyScope='accounts',taskAssignee='';
const moneyExact=v=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(Number(v)||0);
Object.assign(kindNames,{project:'Verkaufschance',ticket:'Servicefall',appointment:'Termin',campaign:'Kampagne',task_template:'Aufgabenvorlage',document:'Dokumentlink',saved_view:'Ansicht'});
Object.assign(labels,{customer_number:'Kundennummer',customer_status:'Beziehungsstatus',street:'Straße / Hausnummer',postal_code:'Postleitzahl',city:'Ort',country:'Land',tags:'Schlagwörter (mit Komma trennen)',account_note:'Hinweis zur Kundenbeziehung',probability:'Abschlusswahrscheinlichkeit (%)',expected_close:'Erwarteter Abschluss',forecast_category:'Prognosekategorie',next_step:'Nächster vereinbarter Schritt',department:'Abteilung',newsletter_status:'Newsletter-Einwilligung',consent_at:'Nachweis vom',do_not_contact:'Kontaktsperre',review_at:'Kontaktangaben prüfen am',location:'Ort / Besprechungslink',resolution:'Lösung / Abschlussvermerk',category:'Kategorie',url:'Dokument-Adresse',payment_terms:'Zahlungsbedingungen',introduction:'Angebotstext',expected_value:'Chancenwert netto (€)'});
Object.assign(enums,{customer_status:{prospect:'Interessent',customer:'Kunde',partner:'Partner',inactive:'Inaktiv'},newsletter_status:{unknown:'Nicht geklärt',opted_in:'Dokumentiert eingewilligt',opted_out:'Abgemeldet / widersprochen'},forecast_category:{pipeline:'Pipeline',best_case:'Best Case',commit:'Verbindliche Prognose',omit:'Nicht berücksichtigen'}});
fieldsets.company.push('customer_number','customer_status','street','postal_code','city','country','tags','account_note');
fieldsets.project.push('probability','expected_close','forecast_category','next_step','tags');
fieldsets.contact.push('department','newsletter_status','consent_at','do_not_contact','review_at');
Object.assign(fieldsets,{ticket:['title','description','status','priority','assignee_id','due_at','category','resolution'],appointment:['title','starts_at','ends_at','location','status','description','assignee_id'],document:['title','url','description','category'],campaign:['title','status','industry','tag','description','starts_at','ends_at']});
Object.assign(stateNames,{in_progress:'In Bearbeitung',waiting:'Wartet auf Kunde',resolved:'Gelöst',closed:'Geschlossen',planned:'Geplant',active:'Aktiv',completed:'Abgeschlossen'});
const pick=(label,id,options,value='',blank='Alle')=>`<select id="${id}" aria-label="${esc(label)}">${selectOptions(options,value,blank)}</select>`;
const vbutton=(label,a,id='',cls='small')=>`<button class="${cls}" data-v2="${a}" data-id="${esc(id)}">${esc(label)}</button>`;
const accountButton=id=>`<button class="cell-link" data-account="${id}">${esc(title(id))}</button>`;
function relevantProjects(id){return projectRows().filter(p=>p.data.company_id===id);}
function relatedCompany(id){const ids=new Set(relevantProjects(id).map(p=>p.id));return db.records.filter(r=>ids.has(r.project_id));}
function openProjects(){return projectRows().filter(p=>!['won','lost'].includes(p.data.stage)&&!p.data.paused);}
function qualifiedForecast(p){return p.data.expected_value!==null&&p.data.expected_value!==undefined&&p.data.expected_value!==''&&p.data.probability!==null&&p.data.probability!==undefined&&p.data.probability!==''&&!!p.data.expected_close;}
function weighted(p){return qualifiedForecast(p)&&p.data.forecast_category!=='omit'?Number(p.data.expected_value)*Number(p.data.probability)/100:0;}
function contactCompany(c){return byId(c.project_id)?.data.company_id;}
function badgeConsent(c){return c.data.do_not_contact?tag('Kontaktsperre','red'):tag(enums.newsletter_status[c.data.newsletter_status]||'Einwilligung offen',c.data.newsletter_status==='opted_in'?'':'warn');}
field=function(key,value='',kind='',wide=false){
 const special={ticket:{status:{open:'Offen',in_progress:'In Bearbeitung',waiting:'Wartet auf Kunde',resolved:'Gelöst',closed:'Geschlossen'},priority:{low:'Niedrig',normal:'Normal',high:'Hoch',urgent:'Dringend'}},appointment:{status:{planned:'Geplant',done:'Durchgeführt',cancelled:'Abgesagt'}},campaign:{status:{planned:'Geplant',active:'Aktiv',completed:'Abgeschlossen',cancelled:'Abgebrochen'}}};
 if(special[kind]?.[key])return `<label class="field">${esc(labels[key])}<select name="${key}">${selectOptions(Object.entries(special[kind][key]),value)}</select></label>`;
 if(key==='do_not_contact')return `<label class="field">Kontaktsperre<select name="do_not_contact"><option value="false">Nein</option><option value="true" ${value===true?'selected':''}>Ja – nicht kontaktieren</option></select></label>`;
 if(['expected_close','consent_at','review_at'].includes(key))return `<label class="field">${labels[key]}<input name="${key}" type="date" value="${esc(value?String(value).slice(0,10):'')}"></label>`;
 if(key==='probability')return `<label class="field">${labels[key]}<input name="probability" type="number" min="0" max="100" step="1" value="${esc(value)}" placeholder="Noch nicht bewertet"></label>`;
 return oldField(key,value,kind,wide);
};
formData=function(f){const d=oldFormData(f);if('do_not_contact'in d)d.do_not_contact=d.do_not_contact==='true';return d;};
navigate=function(next){page=next;selected=null;accountId=null;search='';draw();$('#sidebar').classList.remove('open');window.scrollTo(0,0);};
draw=function(){if(!db)return;
 const groups=[['Arbeitsplatz',[['overview','◫','Übersicht'],['tasks','✓','Aktivitäten & Aufgaben'],['appointments','▦','Kalender']]],['Kunden & Vertrieb',[['contacts','▣','Unternehmen'],['people','◎','Kontakte'],['projects','▥','Verkaufschancen'],['offers','▧','Angebote & Aufträge'],['support','◉','Kundenservice']]],['Projektdurchführung',[['portfolio','▰','Kundenprojekte'],['times','◷','Zeiterfassung']]],['Organisation',[['services','◇','Leistungskatalog'],['templates','☷','Aufgabenvorlagen'],['quality','◌','Datenqualität'],...(isManager()?[['campaigns','◈','Kampagnen']]:[])]],['Auswertung',[['forecast','↗','Umsatzprognose'],...(isManager()?[['analytics','▤','Team & Vertrieb'],['bonus','€','Prämien'],['history','↺','Änderungsverlauf']]:[])]],['Werkzeuge',[['capture','＋','Messegespräch'],['assistant','✦','Assistent'],['settings','⚙','Einstellungen']]]];
 $('#nav').innerHTML=groups.map(([label,items])=>`<div class="nav-label">${label}</div>`+items.map(([id,icon,label])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><i>${icon}</i>${label}</button>`).join('')).join('');
 $('#user-name').textContent=user.name;$('#user-role').textContent=isManager()?'Geschäftsführung':'Beratung';
 const views={portfolio:portfolioView,times:timesView,overview:homeV2,contacts:companiesV2,people:peopleV2,projects:projectsV2,tasks:tasksV2,offers:offersV2,appointments:calendarV2,support:supportV2,services:oldServices,templates:templatesV2,quality:qualityV2,campaigns:campaignsV2,forecast:forecastV2,analytics,bonus,history:historyView,settings:settingsV2,capture:captureView,assistant:assistantView};
 $('#workspace').innerHTML=accountId?companyDetailV2():selected?projectDetail():((views[page]||homeV2)());
 if(page==='capture'&&!selected&&!accountId)bindCapture();bindPage();bindWorkspace();
};
$('.brand small').textContent='CUSTOMER RELATIONSHIP MANAGEMENT';
$('#app .brand').innerHTML='train<span>today</span><small>CRM · VERTRIEB & SERVICE</small>';
$('#app .sidebar-bottom p').textContent='Train Today CRM · v2.0';
$('#login-form h2').textContent='Dein CRM-Arbeitsplatz';
$('#login-form .muted').textContent='Kunden, Verkaufschancen und Zusammenarbeit an einem Ort.';
$('.topbar>strong').outerHTML='<form id="global-search" class="global-search"><input name="q" aria-label="Globale Suche" placeholder="Kunden, Kontakte, Chancen suchen …" autocomplete="off"></form>';
$('#global-search').onsubmit=e=>{e.preventDefault();searchAll(new FormData(e.target).get('q'));};

function homeV2(){const open=openProjects(),tasks=rows('task').filter(t=>t.data.status==='open'&&(isManager()||t.data.assignee_id===user.id)),late=tasks.filter(t=>t.data.due_at&&new Date(t.data.due_at)<new Date()),known=open.filter(qualifiedForecast),tickets=rows('ticket').filter(t=>!['resolved','closed'].includes(t.data.status));
 return head('Arbeitsplatz',`Guten Tag, ${user.name.split(' ')[0]}.`,'Dein Überblick über Kundenbeziehungen, Vertrieb und nächste Schritte.',`<button class="primary" data-nav="capture">+ Messegespräch</button>`)+
 (queue().length?`<div class="notice">${queue().length} Gespräche warten auf Übertragung. ${btn('Übertragen','sync-queue')}</div>`:'')+
 `<div class="metrics">${metric('Offene Verkaufschancen',open.length,'im eigenen Zugriffsbereich',true)}${metric('Gewichtete Pipeline',money(known.reduce((s,p)=>s+weighted(p),0)),known.length+' von '+open.length+' Chancen bewertet')}${metric('Offene Aufgaben',tasks.length,late.length+' davon überfällig')}${metric('Offene Servicefälle',tickets.length,'Kundenanliegen im Blick')}</div><div class="split"><section><div class="card"><div class="section-title"><h2>Vertriebspipeline</h2><button class="small" data-nav="projects">Alle Chancen →</button></div>${Object.entries(stageNames).filter(([k])=>!['won','lost'].includes(k)).map(([k,v])=>{const n=open.filter(p=>p.data.stage===k).length;return `<div class="forecast-row"><span>${v}</span><div class="bar"><span style="width:${open.length?n/open.length*100:0}%"></span></div><strong>${n} Chancen</strong></div>`;}).join('')}<p class="caption">${open.length-known.length} Chancen fehlen Wert, Wahrscheinlichkeit oder Abschlussdatum. Diese gehen noch nicht in die gewichtete Prognose ein.</p></div><div class="card"><div class="section-title"><h2>Anstehende Aufgaben</h2><button class="small" data-nav="tasks">Alle Aufgaben →</button></div>${taskList(tasks.sort((a,b)=>(a.data.due_at||'9999').localeCompare(b.data.due_at||'9999')).slice(0,5))}</div></section><aside><div class="card"><div class="section-title"><h2>Zuletzt bearbeitet</h2></div>${projectRows().sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,5).map(p=>`<div class="list-item"><div>${accountButton(p.data.company_id)}<p>${esc(p.data.title)}</p><small class="muted">${esc(name(p.owner_id))}</small></div>${pbutton(p.id)}</div>`).join('')}</div><div class="card"><h2>Datenqualität</h2><p class="muted">Offene Angaben gezielt vervollständigen, bevor Angebote oder Folgeaktionen starten.</p><div class="list-item"><span>Chancen ohne nächste Aufgabe</span><strong class="quality-count">${open.filter(p=>!rows('task').some(t=>t.project_id===p.id&&t.data.status==='open')).length}</strong></div><div class="list-item"><span>Kontakte ohne E-Mail</span><strong class="quality-count">${rows('contact').filter(c=>!c.data.email).length}</strong></div><button class="small" data-nav="quality">Prüfliste öffnen →</button></div></aside></div>`;
}
function companiesV2(){const companies=rows('company').filter(c=>([c.data.name,c.data.customer_number,c.data.city,c.data.industry,c.data.tags].join(' ')).toLowerCase().includes(companyQuery.toLowerCase())&&(!companyScope||(String(c.data.tags||'').includes('Altimport')?companyScope==='imports':companyScope==='accounts')));
 return head('Kundenstamm','Unternehmen','Eine gemeinsame Kundenakte verbindet Kontakte, Chancen, Aufgaben und Belege.',isManager()?'<button class="primary" data-new="company">+ Unternehmen</button>':'')+`<div class="toolbar"><input id="company-query" aria-label="Unternehmen filtern" placeholder="Name, Kundennummer, Ort oder Schlagwort" value="${esc(companyQuery)}">${pick('Kundenakten oder Altimport','company-scope',[['accounts','Kundenakten'],['imports','Alte Importplatzhalter']],companyScope,'Alle Einträge')}<span class="muted tiny">${companies.length} Unternehmen</span></div>`+table(['Unternehmen','Beziehung','Branche / Ort','Chancen','Offene Aufgaben',''],companies.map(c=>{const ps=relevantProjects(c.id),rel=relatedCompany(c.id);return `<tr><td><div class="identity"><span class="avatar">${esc(c.data.name?.slice(0,2).toUpperCase())}</span><div>${accountButton(c.id)}<small>${esc(c.data.customer_number||'Noch keine Kundennummer')}</small></div></div></td><td>${tag(enums.customer_status[c.data.customer_status]||'Nicht eingestuft','blue')}</td><td>${esc(c.data.industry||'Nicht erfasst')}<small>${esc(c.data.city||'Ort nicht erfasst')}</small></td><td>${ps.length}</td><td>${rel.filter(x=>x.kind==='task'&&x.data.status==='open').length}</td><td>${vbutton('Kundenakte','account',c.id)}</td></tr>`;}).join(''));
}
function contactTable(items){return table(['Kontakt','Unternehmen / Chance','Funktion','Kontaktstatus',''],items.map(c=>`<tr><td><strong>${esc(c.data.name||'Name offen')}</strong><small>${esc(c.data.email||'Keine E-Mail')}</small><small>${esc(c.data.phone||'')}</small></td><td>${accountButton(contactCompany(c))}<small>${esc(title(c.project_id))}</small></td><td>${esc(c.data.role||'Nicht erfasst')}<small>${esc(c.data.department||'')}</small></td><td>${badgeConsent(c)}<small>${esc(c.data.contact_preference||'')}</small></td><td>${btn('Bearbeiten','edit',c.id)}</td></tr>`).join(''));}
function peopleV2(){const contacts=rows('contact').filter(c=>([c.data.name,c.data.email,c.data.role,title(contactCompany(c))].join(' ')).toLowerCase().includes(contactQuery.toLowerCase())&&(!contactStatus||(contactStatus==='blocked'?c.data.do_not_contact:(c.data.newsletter_status||'unknown')===contactStatus)));
 return head('Kundenstamm','Kontakte','Ansprechpartner mit Funktion, Projektbezug und dokumentiertem Kontaktwunsch.',vbutton('+ Kontakt','new-contact','','primary'))+`<div class="toolbar"><input id="contact-query" aria-label="Kontakte filtern" placeholder="Name, Unternehmen, E-Mail oder Funktion" value="${esc(contactQuery)}">${pick('Kontaktstatus','contact-status',[['blocked','Kontaktsperre'],...Object.entries(enums.newsletter_status)],contactStatus,'Alle Kontaktstatus')}<span class="muted tiny">${contacts.length} Kontakteinträge</span></div>`+contactTable(contacts)+`<p class="caption">Kontakte bleiben projektbezogen. Mögliche doppelte Personen werden in der Datenqualität zur Prüfung angezeigt.</p>`;
}
function companyDetailV2(){const c=byId(accountId);if(!c)return companiesV2();const ps=relevantProjects(c.id),rel=relatedCompany(c.id),open=ps.filter(p=>!['won','lost'].includes(p.data.stage));
 const tabs=[['overview','Übersicht'],['contacts','Kontakte'],['opportunities','Verkaufschancen'],['timeline','Aktivitäten'],['documents','Angebote & Dokumente'],['service','Service']];
 let body='';if(accountTab==='overview')body=`<div class="metrics">${metric('Verkaufschancen',ps.length,open.length+' noch offen')}${metric('Chancenwert',money(open.reduce((s,p)=>s+Number(p.data.expected_value||0),0)),'Nur eingetragene Werte')}${metric('Aufgaben',rel.filter(r=>r.kind==='task'&&r.data.status==='open').length,'offene nächste Schritte')}${metric('Kontakte',rel.filter(r=>r.kind==='contact').length,'projektbezogene Einträge')}</div><div class="split"><div class="card"><h2>Stammdaten</h2>${[['Kundennummer',c.data.customer_number],['Beziehung',enums.customer_status[c.data.customer_status]],['Branche',c.data.industry],['Unternehmensgröße',c.data.size],['Adresse',[c.data.street,c.data.postal_code,c.data.city,c.data.country].filter(Boolean).join(', ')],['Schlagwörter',c.data.tags],['Website',c.data.website],['Zuletzt geprüft',c.data.checked_at?date(c.data.checked_at):'']].map(([l,v])=>`<div class="list-item"><span class="muted">${l}</span><strong>${esc(v||'Noch nicht erfasst')}</strong></div>`).join('')}<p class="help">${esc(c.data.account_note||'')}</p></div><div class="card"><h2>Nächste Schritte</h2>${taskList(rel.filter(r=>r.kind==='task'&&r.data.status==='open').slice(0,5))}</div></div>`;
 if(accountTab==='contacts')body=contactTable(rel.filter(r=>r.kind==='contact'));
 if(accountTab==='opportunities')body=opportunityTable(ps);
 if(accountTab==='timeline')body=`<div class="card"><h2>Chronologische Kundenakte</h2><div class="timeline">${rel.filter(r=>['conversation','activity','appointment','ticket'].includes(r.kind)).sort((a,b)=>(b.data.occurred_at||b.created_at).localeCompare(a.data.occurred_at||a.created_at)).map(r=>`<article class="timeline-item"><strong>${kindNames[r.kind]} · ${esc(r.data.title||r.data.type||'Gespräch')}</strong><small class="muted"> · ${stamp(r.data.occurred_at||r.created_at)} · ${esc(name(r.owner_id))}</small><p class="help">${esc(title(r.project_id))}</p><div class="note">${esc(r.data.notes||r.data.note||r.data.description||'')}</div></article>`).join('')||'<p class="empty">Noch keine Aktivitäten.</p>'}</div></div>`;
 if(accountTab==='documents')body=offerTable(rel.filter(r=>r.kind==='offer'))+table(['Dokument','Art','Chance',''],rel.filter(r=>r.kind==='document').map(r=>`<tr><td><a href="${esc(r.data.url)}" target="_blank" rel="noopener noreferrer">${esc(r.data.title)} ↗</a></td><td>${esc(r.data.category)}</td><td>${esc(title(r.project_id))}</td><td>${btn('Bearbeiten','edit',r.id)}</td></tr>`).join(''));
 if(accountTab==='service')body=ticketTable(rel.filter(r=>r.kind==='ticket'));
 return `<div class="toolbar"><button data-nav="contacts">← Unternehmen</button>${tag('Kundenakte','blue')}</div>`+head('Kundenbeziehung',c.data.name,'Alle Informationen aus deinem berechtigten Zugriffsbereich.',isManager()?btn('Stammdaten bearbeiten','edit',c.id,''):'')+`<div class="tabs">${tabs.map(([k,v])=>vbutton(v,'account-tab',k,k===accountTab?'active':'')).join('')}</div>`+body;
}
function filteredProjects(){return projectRows().filter(p=>(p.data.title+' '+title(p.data.company_id)+' '+(p.data.tags||'')).toLowerCase().includes(filters.q.toLowerCase())&&(!filters.stage||p.data.stage===filters.stage)&&(!filters.owner||p.owner_id===filters.owner)&&(!filters.event||p.data.event_id===filters.event)&&(!filters.risk||filters.risk==='no_task'&&!rows('task').some(t=>t.project_id===p.id&&t.data.status==='open')||filters.risk==='incomplete'&&!qualifiedForecast(p)||filters.risk==='overdue'&&p.data.expected_close&&new Date(p.data.expected_close)<new Date()&&!['won','lost'].includes(p.data.stage)));}
function opportunityTable(ps){return table(['Verkaufschance','Verantwortlich','Phase','Wert netto','Abschluss / Wahrscheinlichkeit',''],ps.map(p=>`<tr><td><strong>${esc(p.data.title)}</strong>${accountButton(p.data.company_id)}${p.data.next_step?'<small>'+esc(p.data.next_step)+'</small>':''}</td><td>${esc(name(p.owner_id))}</td><td>${tag(stageNames[p.data.stage],'blue')}${p.data.paused?tag('Pausiert','warn'):''}</td><td>${p.data.expected_value!=null?money(p.data.expected_value):'Noch offen'}</td><td>${date(p.data.expected_close)}<small>${p.data.probability!=null?esc(p.data.probability)+' %':'Noch nicht bewertet'}</small></td><td>${pbutton(p.id)}</td></tr>`).join(''));}
function projectsV2(){const ps=filteredProjects(),views=rows('saved_view');return head('Vertrieb','Verkaufschancen','Verfolge echte Kundenprojekte vom Bedarf bis zum Auftrag.',vbutton('+ Verkaufschance','new-opportunity','','primary'))+`<div class="toolbar"><input id="opportunity-query" class="filter-wide" aria-label="Chancen suchen" placeholder="Unternehmen, Chance oder Schlagwort" value="${esc(filters.q)}">${pick('Phase','filter-stage',Object.entries(stageNames),filters.stage,'Alle Phasen')}${pick('Verantwortlich','filter-owner',db.people.filter(p=>p.active).map(p=>[p.id,p.name]),filters.owner,'Alle Verantwortlichen')}${pick('Messe','filter-event',rows('event').map(e=>[e.id,e.data.name]),filters.event,'Alle Messen')}${pick('Prüfkriterium','filter-risk',[['no_task','Ohne offene Aufgabe'],['incomplete','Prognose unvollständig'],['overdue','Abschlussdatum überfällig']],filters.risk,'Alle Chancen')}</div><div class="toolbar">${pick('Gespeicherte Ansicht','saved-view',views.map(v=>[v.id,v.data.title]),'','Meine gespeicherten Ansichten')}${vbutton('Ansicht speichern','save-view')}${vbutton(filters.mode==='board'?'Liste':'Board','toggle-board')}${vbutton('CSV exportieren','export-opportunities')}${vbutton('Filter zurücksetzen','reset-filters')}</div><div class="pipeline-summary"><strong>${ps.length} Chancen</strong><span>${money(ps.reduce((s,p)=>s+Number(p.data.expected_value||0),0))} erfasster Chancenwert</span></div>`+(filters.mode==='board'?`<div class="kanban">${Object.entries(stageNames).map(([k,v])=>`<section class="column"><h3>${v} ${tag(ps.filter(p=>p.data.stage===k).length)}</h3>${ps.filter(p=>p.data.stage===k).map(p=>`<article class="project-card" data-project="${p.id}" role="button" tabindex="0"><small class="muted">${esc(title(p.data.company_id))}</small><h3>${esc(p.data.title)}</h3><p class="tiny">${esc(name(p.owner_id))}</p><div class="pillrow">${tag(p.data.expected_value!=null?money(p.data.expected_value):'Wert offen','blue')}${tag(p.data.probability!=null?p.data.probability+' %':'Bewertung offen')}</div><small class="muted">Abschluss: ${date(p.data.expected_close)}</small></article>`).join('')}</section>`).join('')}</div>`:opportunityTable(ps));}
projectDetail=function(){const p=byId(selected);if(!p)return '';const extra=`<div class="card"><div class="section-title"><h2>CRM-Planung</h2>${accountButton(p.data.company_id)}</div><div class="grid"><p>Chancenwert: <strong>${p.data.expected_value!=null?money(p.data.expected_value):'Offen'}</strong><br>Abschluss: <strong>${date(p.data.expected_close)}</strong></p><p>Wahrscheinlichkeit: <strong>${p.data.probability!=null?p.data.probability+' %':'Offen'}</strong><br>Prognose: <strong>${esc(enums.forecast_category[p.data.forecast_category]||'Pipeline')}</strong></p></div><p>Nächster Schritt: ${esc(p.data.next_step||'Noch vereinbaren')}</p><div class="toolbar">${vbutton('Aufgabenvorlage anwenden','apply-template',p.id)}${vbutton('+ Servicefall','new-ticket',p.id)}${vbutton('+ Termin','new-appointment',p.id)}${vbutton('+ Dokumentlink','new-document',p.id)}</div>${table(['Zusätzlicher Vorgang','Status / Termin',''],db.records.filter(r=>r.project_id===p.id&&['ticket','appointment','document'].includes(r.kind)).map(r=>`<tr><td><strong>${esc(r.data.title)}</strong><small>${kindNames[r.kind]}</small></td><td>${esc(stateNames[r.data.status]||r.data.category||'')}${r.data.starts_at?'<small>'+stamp(r.data.starts_at)+'</small>':''}</td><td>${btn('Öffnen','edit',r.id)}</td></tr>`).join(''))}</div>`;return oldProjects()+extra;};

function forecastV2(){const open=openProjects(),known=open.filter(p=>qualifiedForecast(p)&&p.data.forecast_category!=='omit'),missing=open.filter(p=>!qualifiedForecast(p)),monthKeys=[...new Set(known.map(p=>String(p.data.expected_close).slice(0,7)))].sort();
 return head('Vertriebssteuerung','Umsatzprognose','Erwartete Abschlüsse und gewichtete Chancenwerte. Eine Prognose ist kein Zahlungseingang.')+`<div class="metrics">${metric('Bewertete Pipeline',money(known.reduce((s,p)=>s+Number(p.data.expected_value),0)),known.length+' vollständig bewertete Chancen',true)}${metric('Gewichtete Prognose',money(known.reduce((s,p)=>s+weighted(p),0)),'Chancenwert × Wahrscheinlichkeit')}${metric('Verbindliche Prognose',money(known.filter(p=>p.data.forecast_category==='commit').reduce((s,p)=>s+Number(p.data.expected_value),0)),'Manuell als verbindlich eingestuft')}${metric('Angaben fehlen',missing.length,'Wert, Datum oder Wahrscheinlichkeit')}</div>`+table(['Abschlussmonat','Chancen','Chancenwert netto','Gewichtet netto','Verbindliche Prognose netto'],monthKeys.map(m=>{const ps=known.filter(p=>p.data.expected_close.startsWith(m));return `<tr><td><strong>${esc(m)}</strong></td><td>${ps.length}</td><td>${money(ps.reduce((s,p)=>s+Number(p.data.expected_value),0))}</td><td>${money(ps.reduce((s,p)=>s+weighted(p),0))}</td><td>${money(ps.filter(p=>p.data.forecast_category==='commit').reduce((s,p)=>s+Number(p.data.expected_value),0))}</td></tr>`;}).join(''))+`<div class="report-note">Pausierte, gewonnene, verlorene und ausdrücklich ausgeschlossene Chancen zählen nicht zur offenen Prognose. Ein fehlendes Budget wird nicht automatisch als Chancenwert verwendet. Die Prämienberechnung nutzt weiterhin bestätigte Zahlungen und Kosten.</div><h2 style="margin-top:24px">Noch zu bewerten</h2>`+opportunityTable(missing);
}
function offerTable(items){return table(['Angebot','Kunde / Chance','Netto / Brutto','Status',''],items.map(o=>`<tr><td><strong>${esc(o.data.reference||'Ohne Nummer')}</strong><small>${esc(o.data.title)}</small></td><td>${accountButton(byId(o.project_id)?.data.company_id)}<small>${esc(title(o.project_id))}</small></td><td>${moneyExact(o.data.amount)}<small>${o.data.gross_total!=null?moneyExact(o.data.gross_total)+' brutto':'Positionen noch offen'}</small></td><td>${tag(stateNames[o.data.status]||o.data.status,'blue')}<small>Gültig bis ${date(o.data.valid_until)}</small></td><td><div class="pillrow">${btn('Bearbeiten','edit',o.id)}${vbutton('Vorschau','preview-offer',o.id)}${vbutton('Neue Fassung','revise-offer',o.id)}${isManager()&&o.data.status==='accepted'?vbutton('Auftrag','convert-offer',o.id):''}</div></td></tr>`).join(''));}
function offersV2(){return head('Vertrieb','Angebote & Aufträge','Angebote mit Positionen, Rabatt und Steuer. Aufträge werden bewusst bestätigt.',vbutton('+ Angebot','new-offer','','primary'))+offerTable(rows('offer'))+'<h2>Bestätigte Aufträge und Zahlungen</h2>'+table(['Auftragsnummer','Chance','Wert netto','Zahlungen netto',''],rows('order').map(o=>`<tr><td><strong>${esc(o.data.reference)}</strong>${o.data.source_offer_id?'<small>Aus Angebot übernommen</small>':''}</td><td>${esc(title(o.project_id))}</td><td>${moneyExact(o.data.amount)}</td><td>${moneyExact(Number(o.data.paid_amount||0)-Number(o.data.refund_amount||0))}${o.data.cancelled?tag('Storniert','red'):''}</td><td>${isManager()?btn('Bearbeiten','edit',o.id):pbutton(o.project_id)}</td></tr>`).join(''));}
function ticketTable(items){return table(['Servicefall','Kunde / Chance','Status','Priorität / Fälligkeit','Zuständig',''],items.map(t=>`<tr><td><strong>${esc(t.data.title)}</strong><small>${esc(t.data.category||'Allgemein')}</small></td><td>${accountButton(byId(t.project_id)?.data.company_id)}<small>${esc(title(t.project_id))}</small></td><td>${tag(stateNames[t.data.status],'blue')}</td><td>${tag(({urgent:'Dringend',high:'Hoch',normal:'Normal',low:'Niedrig'})[t.data.priority]||'Normal',t.data.priority==='urgent'?'red':'')}<small>${date(t.data.due_at)}</small></td><td>${esc(name(t.data.assignee_id||t.owner_id))}</td><td>${btn('Bearbeiten','edit',t.id)}</td></tr>`).join(''));}
function supportV2(){return head('Kundenbetreuung','Servicefälle','Fragen, Reklamationen und Betreuungsbedarf mit Zuständigkeit und dokumentierter Lösung.',vbutton('+ Servicefall','new-ticket','','primary'))+`<div class="toolbar">${pick('Servicestatus','support-status',[['open','Offen'],['in_progress','In Bearbeitung'],['waiting','Wartet auf Kunde'],['resolved','Gelöst'],['closed','Geschlossen']],supportStatus,'Alle Status')}</div>`+ticketTable(rows('ticket').filter(t=>!supportStatus||t.data.status===supportStatus));}
function calendarV2(){const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-(start.getDay()+6)%7+agendaOffset*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d;});
 return head('Arbeitsplatz','Kalender','Lokale Kundentermine und fällige Aufgaben. Kalenderdateien lassen sich separat exportieren.',vbutton('+ Termin','new-appointment','','primary'))+`<div class="toolbar">${vbutton('← Vorige Woche','week-prev')}${vbutton('Diese Woche','week-now')}${vbutton('Nächste Woche →','week-next')}<strong>${date(days[0])} – ${date(days[6])}</strong></div><div class="calendar-week">${days.map(d=>`<div><h3>${d.toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})}</h3>${rows('appointment').filter(a=>new Date(a.data.starts_at).toDateString()===d.toDateString()).sort((a,b)=>a.data.starts_at.localeCompare(b.data.starts_at)).map(a=>`<div class="agenda-day ${a.data.status==='cancelled'?'cancelled':''}"><time>${new Date(a.data.starts_at).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</time><h3>${esc(a.data.title)}</h3><p class="tiny">${esc(title(a.project_id))}</p>${btn('Öffnen','edit',a.id)} ${vbutton('ICS','appointment-ics',a.id)}</div>`).join('')}${rows('task').filter(t=>t.data.status==='open'&&t.data.due_at&&new Date(t.data.due_at).toDateString()===d.toDateString()).map(t=>`<div class="subtle tiny">✓ ${esc(t.data.title)}<br>${btn('Aufgabe','edit',t.id)}</div>`).join('')}</div>`).join('')}</div><p class="caption">Noch keine Synchronisation mit Outlook oder Google Kalender. Keine Einladungen werden automatisch verschickt.</p>`;
}
function templatesV2(){return head('Organisation','Aufgabenvorlagen','Wiederkehrende Abläufe als konkrete Aufgaben für eine Verkaufschance anlegen.',isManager()?vbutton('+ Vorlage','new-template','','primary'):'')+table(['Vorlage','Schritte',''],rows('task_template').map(t=>`<tr><td><strong>${esc(t.data.title)}</strong><small>${esc(t.data.description)}</small></td><td>${t.data.steps.map(s=>`<div>+${s.days} Tage · ${esc(s.title)}</div>`).join('')}</td><td>${vbutton('Anwenden','choose-template',t.id)} ${isManager()?vbutton('Bearbeiten','edit-template',t.id):''}</td></tr>`).join(''))+`<div class="report-note">Jede Anwendung erstellt eigene Aufgaben mit Startdatum und Zuständigkeit. Wiederholte technische Übertragungen derselben Anfrage erzeugen keine doppelten Aufgaben.</div>`;}
function qualityV2(){const emails=new Map();for(const c of rows('contact'))if(c.data.email){const key=c.data.email.trim().toLowerCase();emails.set(key,[...(emails.get(key)||[]),c]);}const doubles=[...emails].filter(([,cs])=>cs.length>1),p=projectRows(),orphans=rows('company').filter(c=>!p.some(x=>x.data.company_id===c.id));
 return head('Organisation','Datenqualität','Prüfhinweise helfen beim Abgleich. Bestehende Daten werden niemals automatisch zusammengeführt oder gelöscht.')+`<div class="metrics">${metric('Mehrfach verwendete E-Mails',doubles.length,'Personenabgleich erforderlich')}${metric('Unternehmen ohne Chance',orphans.length,'einschließlich alter Platzhalter')}${metric('Kontaktangaben prüfen',rows('contact').filter(c=>c.data.review_at&&new Date(c.data.review_at)<new Date()).length,'Prüftermin überschritten')}${metric('Prognose unvollständig',openProjects().filter(p=>!qualifiedForecast(p)).length,'Angaben nachtragen')}</div><h2>Mögliche Kontakt-Dubletten</h2>`+table(['E-Mail','Kontakte / Projektzuordnung'],doubles.map(([email,cs])=>`<tr><td>${esc(email)}</td><td>${cs.map(c=>`<div>${esc(c.data.name)} · ${esc(title(c.project_id))} ${btn('Prüfen','edit',c.id)}</div>`).join('')}</td></tr>`).join(''))+'<h2>Unternehmen ohne zugeordnete Chance</h2>'+table(['Unternehmen',''],orphans.map(c=>`<tr><td>${accountButton(c.id)}</td><td>${vbutton('Kundenakte','account',c.id)}</td></tr>`).join(''))+'<h2>Kontaktdaten mit fälliger Prüfung</h2>'+contactTable(rows('contact').filter(c=>c.data.review_at&&new Date(c.data.review_at)<new Date()));
}
function campaignRecipients(c){const all=rows('contact'),blocked=new Set(all.filter(x=>x.data.do_not_contact||x.data.newsletter_status==='opted_out').map(x=>(x.data.email||'').trim().toLowerCase()));const seen=new Set();return all.filter(x=>{const company=byId(contactCompany(x)),mail=(x.data.email||'').trim().toLowerCase();if(!mail||blocked.has(mail)||seen.has(mail)||x.data.newsletter_status!=='opted_in'||!x.data.consent_at||!x.data.consent_note?.trim())return false;if(c.data.industry&&!company?.data.industry?.toLowerCase().includes(c.data.industry.toLowerCase()))return false;if(c.data.tag&&!String(company?.data.tags||'').split(',').map(t=>t.trim().toLowerCase()).includes(c.data.tag.toLowerCase()))return false;seen.add(mail);return true;});}
function campaignsV2(){if(!isManager())return '';return head('Marketing','Kampagnen & Zielgruppen','Lokale Kampagnenplanung mit prüfbarer Empfängerliste. Der Versand erfolgt später über einen separaten Workflow.',vbutton('+ Kampagne','new-campaign','','primary'))+table(['Kampagne','Segment','Status','Geeignete E-Mail-Adressen',''],rows('campaign').map(c=>`<tr><td><strong>${esc(c.data.title)}</strong><small>${esc(c.data.description||'')}</small></td><td>${esc(c.data.industry||'Alle Branchen')}<small>${esc(c.data.tag||'Alle Schlagwörter')}</small></td><td>${tag(stateNames[c.data.status],'blue')}</td><td>${campaignRecipients(c).length}</td><td>${btn('Bearbeiten','edit',c.id)} ${vbutton('Empfänger prüfen','campaign-preview',c.id)}</td></tr>`).join(''))+`<div class="report-note">Die Liste enthält nur Kontakte mit dokumentierter Newsletter-Einwilligung, Nachweis und Datum. Eine Kontaktsperre oder Abmeldung bei derselben E-Mail-Adresse schließt diese Adresse aus. Das ersetzt keine Prüfung des konkreten Versandzwecks.</div>`;}
function settingsV2(){return head('System','CRM & Integrationen','Lokale Datenhaltung und ein klarer Übergabepunkt für euren separaten Messe-Workflow.')+`<div class="card"><h2>CRM-Schnittstelle v1</h2><p>Unternehmen, Kontakte, Verkaufschancen, Aufgaben, Aktivitäten, Angebote, Aufträge, Servicefälle und Termine stehen über geschützte Lese-Endpunkte bereit.</p><code>GET /api/v1/companies</code><p class="help">Persönliche Anmeldung und Datensatzrechte gelten auch für die API. Schreibaktionen laufen weiterhin über /api/command mit einer eindeutigen Anfrage-ID. Die API-Dokumentation liegt in CRM-V2-API.txt.</p>${tag('Lokales PostgreSQL','blue')} ${tag('Agent bleibt lesend')}</div>`+oldSettings();}

function bindWorkspace(){
 if($('#company-scope'))$('#company-scope').onchange=e=>{companyScope=e.target.value;draw();};
 if($('#task-assignee'))$('#task-assignee').onchange=e=>{taskAssignee=e.target.value;draw();};
 for(const [id,set]of [['company-query',v=>companyQuery=v],['contact-query',v=>contactQuery=v],['opportunity-query',v=>filters.q=v]])if($('#'+id))$('#'+id).oninput=e=>{set(e.target.value);const pos=e.target.selectionStart;draw();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos);};
 for(const k of ['stage','owner','event','risk'])if($('#filter-'+k))$('#filter-'+k).onchange=e=>{filters[k]=e.target.value;draw();};
 if($('#contact-status'))$('#contact-status').onchange=e=>{contactStatus=e.target.value;draw();};if($('#support-status'))$('#support-status').onchange=e=>{supportStatus=e.target.value;draw();};
 if($('#saved-view'))$('#saved-view').onchange=e=>{const r=byId(e.target.value);if(r){filters={q:'',stage:'',owner:'',event:'',risk:'',mode:'list',...r.data.filters};draw();}};
}
function searchAll(q){q=String(q||'').trim().toLowerCase();if(q.length<2){notify('Mindestens zwei Zeichen eingeben.');return;}const results=db.records.filter(r=>!['saved_view','settlement','rule'].includes(r.kind)&&JSON.stringify(r.data).toLowerCase().includes(q)).slice(0,60);openModal('Suche: '+q,`<div class="search-results">${results.map(r=>`<div class="search-item"><span class="tag blue">${kindNames[r.kind]||r.kind}</span>${vbutton(r.data.title||r.data.name||r.data.reference||r.data.notes?.slice(0,90)||r.kind,'search-open',r.id,'cell-link')}</div>`).join('')||'<p class="empty">Keine passenden Datensätze gefunden.</p>'}</div><p class="help">Bis zu 60 Treffer aus deinem berechtigten Datenbestand.</p>`);}

function chooseProject(callback){openModal('Verkaufschance auswählen',`<form id="choose-project"><label class="field">Kundenprojekt<select name="project_id" required>${selectOptions(projectRows().map(p=>[p.id,title(p.data.company_id)+' · '+p.data.title]))}</select></label><div class="actions"><button class="primary">Weiter</button></div></form>`);$('#choose-project').onsubmit=e=>{e.preventDefault();callback(new FormData(e.target).get('project_id'));};}
editForm=function(kind,id=null,parent=null){if(kind==='offer'){if(!id&&!parent){chooseProject(p=>offerEditor(null,p));return;}return offerEditor(id,parent);}if(kind==='task_template')return templateEditor(id);if(['ticket','appointment','document','contact','task','activity'].includes(kind)&&!id&&!parent){chooseProject(p=>editForm(kind,null,p));return;}oldEdit(kind,id,parent);if(['ticket','appointment'].includes(kind)){const s=$('#edit-form select[name="assignee_id"]'),project=parent||byId(id)?.project_id;if(s){const members=new Set(db.members.filter(m=>m.project_id===project).map(m=>m.user_id));members.add(byId(project)?.owner_id);s.innerHTML=selectOptions(db.people.filter(p=>p.active&&members.has(p.id)).map(p=>[p.id,p.name]),byId(id)?.data.assignee_id||user.id);}}};
function templateEditor(id){const r=byId(id),d=r?.data||{};openModal(r?'Aufgabenvorlage bearbeiten':'Neue Aufgabenvorlage',`<form id="template-form">${field('title',d.title||'')}${field('description',d.description||'')}<label class="field">Schritte – je Zeile: Tage nach Start | Aufgabe<textarea name="steps" rows="7" required placeholder="1 | Gespräch nachbereiten\n3 | Kundenbedarf bestätigen\n7 | Angebot nachfassen">${esc((d.steps||[]).map(s=>s.days+' | '+s.title).join('\n'))}</textarea></label><p class="error" id="form-error"></p><div class="actions"><button class="primary">Vorlage speichern</button></div></form>`);$('#template-form').onsubmit=async e=>{e.preventDefault();const f=formData(e.target),steps=f.steps.split('\n').filter(x=>x.trim()).map(line=>{const sep=line.indexOf('|');return{days:Number(line.slice(0,sep).trim()),title:line.slice(sep+1).trim()};});try{await mutate(r?{action:'update',id,version:r.version,data:{...f,steps}}:{action:'create',kind:'task_template',data:{...f,steps}});$('#modal').close();}catch(e){$('#form-error').textContent=e.message;}};}
function applyTemplate(projectId,templateId=''){openModal('Aufgaben aus Vorlage',`<form id="apply-template"><p class="help">${esc(title(projectId))} · Die neuen Aufgaben werden dir zugeordnet.</p><label class="field">Vorlage<select name="template_id" required>${selectOptions(rows('task_template').map(t=>[t.id,t.data.title]),templateId)}</select></label><label class="field">Startdatum<input type="date" name="base_date" value="${new Date().toLocaleDateString('en-CA')}" required></label><p class="error" id="form-error"></p><div class="actions"><button class="primary">Aufgaben anlegen</button></div></form>`);const request_id=crypto.randomUUID();$('#apply-template').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/command',{method:'POST',body:JSON.stringify({action:'apply_template',request_id,project_id:projectId,...formData(e.target)})});await refresh();$('#modal').close();notify('Aufgaben angelegt.');}catch(e){$('#form-error').textContent=e.message;}finally{b.disabled=false;}};}

function offerEditor(id,parent){const r=byId(id),d=r?.data||{},locked=!!r&&d.status!=='draft';let lines=structuredClone(d.lines?.length?d.lines:[{description:d.title||'',quantity:1,unit_price:d.amount||0,discount:0,tax_rate:19}]);
 openModal(r?'Angebot '+(d.reference||''):'Angebot erstellen',`<form id="offer-form"><div class="fields">${field('title',d.title||'')}${field('reference',d.reference||'')}${field('status',d.status||'draft','offer')}${field('valid_until',d.valid_until||'')}${field('cost',d.cost??'')}${field('payment_terms',d.payment_terms||'')}${field('introduction',d.introduction||'')}</div><h3 style="margin-top:22px">Angebotspositionen</h3>${locked?'<div class="notice">Dieses Angebot wurde bereits ausgegeben. Für Preisänderungen eine neue Fassung anlegen.</div>':''}<div id="offer-lines"></div>${!locked?'<button type="button" id="add-line">+ Position</button>':''}<div id="offer-total" class="quote-total"></div>${field('version_note',d.version_note||'')}<p class="error" id="form-error"></p><div class="actions"><button class="primary">Angebot speichern</button></div></form>`);
 function renderLines(){const disabled=locked?'disabled':'';$('#offer-lines').innerHTML=lines.map((l,i)=>`<div class="line-editor" data-line="${i}"><label>Leistung<input data-key="description" value="${esc(l.description)}" required ${disabled}></label><label>Menge<input data-key="quantity" type="number" min="0.01" step="0.01" value="${l.quantity}" required ${disabled}></label><label>Preis netto<input data-key="unit_price" type="number" min="0" step="0.01" value="${l.unit_price}" required ${disabled}></label><label>Rabatt %<input data-key="discount" type="number" min="0" max="100" step="0.01" value="${l.discount}" ${disabled}></label><label>USt. %<select data-key="tax_rate" ${disabled}>${[0,7,19].map(x=>`<option value="${x}" ${x===Number(l.tax_rate)?'selected':''}>${x}</option>`).join('')}</select></label><button type="button" data-remove="${i}" aria-label="Position entfernen" ${disabled}>×</button></div>`).join('');calc();$('#offer-lines').querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{lines[Number(el.closest('[data-line]').dataset.line)][el.dataset.key]=el.dataset.key==='description'?el.value:Number(el.value);calc();});$('#offer-lines').querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{lines.splice(Number(el.dataset.remove),1);renderLines();});}
 function calc(){let net=0,tax=0;for(const l of lines){const v=Math.round((l.quantity*l.unit_price*(1-l.discount/100)+Number.EPSILON)*100)/100;net+=v;tax+=Math.round((v*l.tax_rate/100+Number.EPSILON)*100)/100;}$('#offer-total').innerHTML=`<div>Netto ${moneyExact(net)} · Umsatzsteuer ${moneyExact(tax)}</div><strong>${moneyExact(net+tax)} brutto</strong>`;}
 renderLines();if($('#add-line'))$('#add-line').onclick=()=>{lines.push({description:'',quantity:1,unit_price:0,discount:0,tax_rate:19});renderLines();};
 if(locked)for(const k of ['reference','valid_until','cost','payment_terms','introduction'])$('#offer-form').elements[k].disabled=true;
 const request_id=crypto.randomUUID();$('#offer-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;try{if(!locked&&!lines.length)throw Error('Mindestens eine Position hinzufügen.');const data=formData(e.target);if(!locked)data.lines=lines;const payload=r?{action:'update',id,version:r.version,data}:{action:'create',kind:'offer',project_id:parent,data};await api('/api/command',{method:'POST',body:JSON.stringify({request_id,...payload})});await refresh();$('#modal').close();notify('Angebot gespeichert.');}catch(e){$('#form-error').textContent=e.message;}finally{button.disabled=false;}};
}
function offerPreview(id){const o=byId(id),p=byId(o.project_id),c=byId(p?.data.company_id),d=o.data;openModal('Angebotsvorschau',`<div class="toolbar no-print">${vbutton('Drucken / PDF','print-offer')}</div><article class="offer-paper"><header><div><strong>TRAIN TODAY</strong><p>Trainings · Beratung · Entwicklung</p></div><div><strong>${esc(d.reference)}</strong><br>${tag(stateNames[d.status]||'Entwurf','blue')}</div></header><hr><p><strong>${esc(c?.data.name)}</strong><br>${esc(c?.data.street||'')}<br>${esc([c?.data.postal_code,c?.data.city].filter(Boolean).join(' '))}</p><h1>${esc(d.title)}</h1><p style="white-space:pre-wrap">${esc(d.introduction||'Vielen Dank für Ihr Interesse an unseren Leistungen.')}</p>${table(['Leistung','Menge','Preis netto','Rabatt','USt.','Netto'],(d.lines||[]).map(l=>`<tr><td>${esc(l.description)}</td><td>${l.quantity}</td><td>${moneyExact(l.unit_price)}</td><td>${l.discount} %</td><td>${l.tax_rate} %</td><td>${moneyExact(Math.round((l.quantity*l.unit_price*(1-l.discount/100)+Number.EPSILON)*100)/100)}</td></tr>`).join(''))}<div class="quote-total"><p>Netto: ${moneyExact(d.amount)}<br>Umsatzsteuer: ${d.tax_total!=null?moneyExact(d.tax_total):'Nicht berechnet'}</p><strong>Gesamt: ${d.gross_total!=null?moneyExact(d.gross_total):'Positionen fehlen'}</strong></div><p>Gültig bis: ${date(d.valid_until)}<br>Zahlungsbedingungen: ${esc(d.payment_terms||'Noch zu vereinbaren')}</p><p class="caption">Angebot · Train Today. Dies ist keine Rechnung.</p></article>`);}
function exportAppointment(id){const a=byId(id),icalText=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),dt=v=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('CRM-Termin.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Train Today//CRM//DE\r\nBEGIN:VEVENT\r\nUID:${a.id}@crm.local\r\nDTSTAMP:${dt(a.updated_at)}\r\nDTSTART:${dt(a.data.starts_at)}\r\nDTEND:${dt(a.data.ends_at)}\r\nSUMMARY:${icalText(a.data.title)}\r\nLOCATION:${icalText(a.data.location)}\r\nDESCRIPTION:${icalText(a.data.description)}\r\nSTATUS:${a.data.status==='cancelled'?'CANCELLED':'CONFIRMED'}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`,'text/calendar');}
async function workspaceAction(a,id){try{
 if(a==='account'){accountId=id;accountTab='overview';selected=null;page='contacts';draw();}
 else if(a==='account-tab'){accountTab=id;draw();}
 else if(a==='toggle-board'){filters.mode=filters.mode==='board'?'list':'board';draw();}
 else if(a==='reset-filters'){filters={q:'',stage:'',owner:'',event:'',risk:'',mode:filters.mode};draw();}
 else if(a==='save-view'){openModal('Eigene Ansicht speichern',`<form id="save-view-form">${field('title')}<p class="help">Die aktuellen Such- und Filtereinstellungen werden nur für deinen Benutzer in der lokalen Datenbank gespeichert.</p><p class="error" id="form-error"></p><div class="actions"><button class="primary">Speichern</button></div></form>`);$('#save-view-form').onsubmit=async e=>{e.preventDefault();try{await mutate({action:'create',kind:'saved_view',data:{title:formData(e.target).title,module:'projects',filters:{...filters}}});$('#modal').close();}catch(e){$('#form-error').textContent=e.message;}};}
 else if(a==='export-opportunities')download('CRM-Verkaufschancen.csv',csv([['ID','Unternehmen','Verkaufschance','Zuständig','Phase','Wert netto','Wahrscheinlichkeit %','Abschluss'],...filteredProjects().map(p=>[p.id,title(p.data.company_id),p.data.title,name(p.owner_id),stageNames[p.data.stage],p.data.expected_value,p.data.probability,p.data.expected_close])]),'text/csv');
 else if(a==='new-opportunity')editForm('project');
 else if(a==='new-contact')chooseProject(p=>editForm('contact',null,p));
 else if(a==='new-offer')chooseProject(p=>offerEditor(null,p));
 else if(['new-ticket','new-appointment','new-document'].includes(a)){const kind=a.slice(4);if(id)editForm(kind,null,id);else chooseProject(p=>editForm(kind,null,p));}
 else if(a==='new-template')templateEditor();else if(a==='edit-template')templateEditor(id);
 else if(a==='apply-template')applyTemplate(id);else if(a==='choose-template')chooseProject(p=>applyTemplate(p,id));
 else if(a==='week-prev'){agendaOffset--;draw();}else if(a==='week-next'){agendaOffset++;draw();}else if(a==='week-now'){agendaOffset=0;draw();}
 else if(a==='appointment-ics')exportAppointment(id);
 else if(a==='preview-offer')offerPreview(id);
 else if(a==='print-offer'){document.body.classList.add('printing-offer');window.print();document.body.classList.remove('printing-offer');}
 else if(a==='revise-offer'){const r=await mutate({action:'revise_offer',id});offerEditor(r.record.id,r.record.project_id);}
 else if(a==='convert-offer')reasoningModal('Angebot als Auftrag bestätigen',d=>mutate({action:'convert_offer',id,reference:d.reference,reason:d.reason}),`<p>Netto ${moneyExact(byId(id).data.amount)} übernehmen. Der Zahlungseingang bleibt zunächst 0 €.</p>${field('reference')}`);
 else if(a==='new-campaign')editForm('campaign');
 else if(a==='campaign-preview'){const c=byId(id),contacts=(await api('/api/v1/campaign-recipients?campaign_id='+id)).records;openModal('Empfängervorschau: '+c.data.title,`<p class="help">${contacts.length} eindeutige, aktuell geeignete E-Mail-Adressen. Kein Versand.</p>${contactTable(contacts)}${vbutton('Geprüfte Liste als CSV','campaign-export',id,'primary')}`);}
 else if(a==='campaign-export'){const c=byId(id),contacts=(await api('/api/v1/campaign-recipients?campaign_id='+id)).records;download('CRM-Kampagnenempfaenger.csv',csv([['Kontakt-ID','Name','E-Mail','Unternehmen','Nachweisdatum','Nachweis'],...contacts.map(c=>[c.id,c.data.name,c.data.email,title(contactCompany(c)),c.data.consent_at,c.data.consent_note])]),'text/csv');notify('Empfängerliste exportiert. Kein Versand ausgeführt.');}
 else if(a==='search-open'){const r=byId(id);$('#modal').close();accountId=null;if(r.kind==='company'){accountId=id;page='contacts';accountTab='overview';selected=null;draw();}else if(r.kind==='project'||r.kind==='conversation'||r.kind==='activity'){selected=r.kind==='project'?r.id:r.project_id;page='projects';draw();}else if(fieldsets[r.kind])editForm(r.kind,id);else if(r.project_id){selected=r.project_id;draw();}}
 }catch(e){notify(e.message);}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-account]');if(a){accountId=a.dataset.account;accountTab='overview';selected=null;page='contacts';draw();window.scrollTo(0,0);return;}const b=e.target.closest('[data-v2]');if(b)workspaceAction(b.dataset.v2,b.dataset.id);const p=e.target.closest('[data-project]');if(p){accountId=null;draw();}});
function tasksV2(){const pending=rows('handoff').filter(h=>h.data.status==='pending'),items=rows('task').filter(t=>!taskAssignee||t.data.assignee_id===taskAssignee);return head('Zusammenarbeit','Aktivitäten & Aufgaben','Aufgaben nach Zuständigkeit prüfen und Projektübergaben bewusst entscheiden.')+`<div class="card"><h2>Angefragte Übergaben</h2>${pending.map(h=>`<div class="list-item"><div><strong>${esc(title(h.project_id))}</strong><small>${esc(name(h.owner_id))} → ${esc(name(h.data.recipient_id))}</small><p>${esc(h.data.note||'')}</p></div>${h.data.recipient_id===user.id?btn('Prüfen','handoff-review',h.id):tag('Antwort ausstehend','warn')}</div>`).join('')||'<p class="muted">Keine offenen Übergaben.</p>'}</div><div class="toolbar">${pick('Aufgaben nach Zuständigkeit','task-assignee',db.people.filter(p=>p.active).map(p=>[p.id,p.id===user.id?'Meine Aufgaben · '+p.name:p.name]),taskAssignee,'Alle Zuständigen')}<span class="muted tiny">${items.filter(t=>t.data.status==='open').length} offene Aufgaben</span></div><div class="card"><h2>Offene Aufgaben</h2>${taskList(items.filter(t=>t.data.status==='open').sort((a,b)=>(a.data.due_at||'9999').localeCompare(b.data.due_at||'9999')))}</div><details><summary>Abgeschlossene Aufgaben</summary><div class="card">${taskList(items.filter(t=>t.data.status!=='open'))}</div></details>`;}
const previousLogout=$('#logout').onclick;$('#logout').onclick=async()=>{accountId=null;selected=null;filters={q:'',stage:'',owner:'',event:'',risk:'',mode:'list'};companyQuery='';contactQuery='';page='overview';await previousLogout();};
